Lemma stepR_store : ltac2:(zQ "i12!h9!jc!l9!ip8!jtc!juc!ipe!iq1!ko5!iqa!hk3!ir1!p9!iv3!lm3!ige!hn7!ivc!kve!jjd!jk8!jl4!jm1!jmc!jnd!ln2!lnd!jqa!lp1!hq2!sf!lt4!lte&>0@1$1@1$0#k0@1$2@1$1@1$0#8&@2$5@2$4^e^7@2$8@1$0#c^5>4segs@1$h0$h3>4regs@2$he@1$0#5@1$1@1$0#k0>2pc@1$1@1$0#k0>3mem~0>3rom~0>2rv@1$2@1$1@1$0#k0>1w@1$1@1$0#i0>2sz$hd>3rs1@1$1@1$0#5>3rs2@1$1@1$0#5>3imm@1$1@1$0#c>0@3$3@1$2@1$1@1$0#i0@2$h5^b^9@2$9@1$1@1$0#i0^5>0@3$3$a@1$h6^6$f>0@3$3@1$2@2$b$7$6@1$hb^7@2$9@2$b$7$6@4$h1$7$6@4$hc^6^5^4^3+4>0@3$3$a@4$h9^e^b@2$5@2$4^d^6@2$8@1$0#c^4@1$e^7$h2@3$3@1$h7$c@2$h8^f@6$d?2fx^e^d^c^b^a@2$h4$c@6$d?2fx^e@2$5^d+4@3$hf^c~1@2$ha@1$e^8@2$4^e^6^b@2$i0^a~1").
Proof.
  intros segs regs pc mem rom rv w sz rs1 rs2 imm Hfetch Hecall Hdecode Hok.
  assert (Hsb : forall u : word,
    Z_to_le_bytes 1%nat (bv_unsigned (bv_extract 0 8 u)) = word_to_le_bytes 1 u).
  { intro u. unfold word_to_le_bytes. cbn [Z_to_le_bytes].
    f_equal. apply bv_eq.
    rewrite !Z_to_bv_unsigned, bv_extract_unsigned, Z.shiftr_0_r.
    apply bv_wrap_bv_wrap. lia. }
  stepR_pipeline Hfetch Hecall Hdecode.
  unfold getr; rewrite ?bv_eqb0_is_x0.
  unfold getr in Hok; rewrite ?bv_eqb0_is_x0 in Hok.
  rewrite !b_addsext.
  destruct sz; cbn [msize_bytes] in Hok |- *; cbv beta iota delta [store_val];
    rewrite Hok; cbv beta iota;
    rewrite write_to_mem_wbytes, ?Hsb, ?store_bytes_low16, ?store_bytes_low32, b_npc4;
    (destruct rv as [r|]; cbv beta iota; [|reflexivity]);
    unfold resv_inval_w;
    match goal with |- context [Z.eqb ?x ?y] => destruct (Z.eqb x y); cbv beta iota; reflexivity end.
Qed.

